import { SAFETY_POLICY_VERSION, COVERAGE_DISCLAIMER, FALLBACK_TEXT } from '@/domain/safety/blocklist'
import type { GraphState } from '../graph-state'
import type { AnalyzeOutput, BudgetOutput } from '../types'
import { createTrace } from '../trace'
import { buildBudgetWorkshopQuestions } from '@/domain/questions/question-audience'

const NODE_ID = 'reportBuilder'

// SAFETY.md: fixed derivation message — never generated by LLM
const SAFETY_DERIVATION_MESSAGE =
  'Por seguridad, este tipo de intervención requiere atención profesional. Contactá un taller o mecánico habilitado.'

function buildBudgetOutput(state: GraphState): BudgetOutput | null {
  if (state.route !== 'budget') return null
  const bs = state.budgetState
  if (!bs) {
    return {
      completenessStatus: 'INVALID',
      computedTotalMinorUnit: null,
      computedTotalIsPartial: false,
      currency: null,
      discrepancy: null,
      lineCount: 0,
      missingLineCount: 0,
    }
  }
  const confirmedLines = bs.lines.filter((l) => l.status === 'confirmed').length
  const missingLines = bs.lines.filter((l) => l.status === 'missing').length
  return {
    completenessStatus: bs.completenessStatus,
    computedTotalMinorUnit: bs.computedTotal,
    computedTotalIsPartial: bs.computedTotalIsPartial,
    currency: bs.currency,
    discrepancy: bs.discrepancy,
    lineCount: confirmedLines + missingLines,
    missingLineCount: missingLines,
  }
}

export async function reportBuilderNode(state: GraphState): Promise<Partial<GraphState>> {
  const startTime = Date.now()
  const { caseId, dataLabel } = state

  try {
    const policyVersion = state.safety?.policyVersion ?? SAFETY_POLICY_VERSION
    const coverageDisclaimer = state.safety?.coverageDisclaimer ?? COVERAGE_DISCLAIMER

    const budget = buildBudgetOutput(state)
    const blocked = state.safety?.blocked ?? false
    // Bugfix 7B: the budget route never had questions; it now gets fixed, mechanic-directed ones
    // computed from the server-side totals (no LLM). Symptom questions come from diagnosisAgent.
    const questions = blocked
      ? []
      : state.route === 'budget' && budget && !state.fallback
        ? buildBudgetWorkshopQuestions(budget)
        : state.questions

    const output: AnalyzeOutput = {
      caseId,
      safetyBlocked: state.safety?.blocked ?? false,
      safetyDerivationMessage: state.safety?.blocked ? SAFETY_DERIVATION_MESSAGE : null,
      policyVersion,
      coverageDisclaimer,
      route: state.safety?.blocked ? null : (state.route ?? null),
      facts: state.safety?.blocked ? [] : state.facts,
      hypotheses: state.safety?.blocked ? [] : state.hypotheses,
      questions,
      driverQuestions: blocked ? [] : state.driverQuestions,
      warnings: state.warnings,
      budget,
      missingInformation: state.missingInformation,
      fallback: state.fallback,
      fallbackText: state.fallback ? FALLBACK_TEXT : null,
      traces: state.traces,
    }

    return {
      output,
      traces: [
        createTrace(caseId, NODE_ID, startTime, state.fallback ? 'fallback_used' : 'success', {
          dataLabel,
          fallbackActivated: state.fallback,
          resultType: state.safety?.blocked ? 'report_blocked' : state.fallback ? 'report_fallback' : 'report_built',
        }),
      ],
    }
  } catch {
    // Last-resort fallback: even reportBuilder failed
    const emergencyOutput: AnalyzeOutput = {
      caseId,
      safetyBlocked: false,
      safetyDerivationMessage: null,
      policyVersion: SAFETY_POLICY_VERSION,
      coverageDisclaimer: COVERAGE_DISCLAIMER,
      route: null,
      facts: [],
      hypotheses: [],
      questions: [],
      warnings: [],
      budget: null,
      missingInformation: [],
      fallback: true,
      fallbackText: FALLBACK_TEXT,
      traces: state.traces,
    }
    return {
      output: emergencyOutput,
      traces: [
        createTrace(caseId, NODE_ID, startTime, 'error', {
          errorCode: 'REPORT_BUILDER_INTERNAL_ERROR',
          dataLabel,
          fallbackActivated: true,
          resultType: 'report_emergency_fallback',
        }),
      ],
    }
  }
}
